// 2 days/week, ~30 min sessions, moderate intensity. Equipment: Resistance bands, Kettlebells.
# Week 1
// Estimated ~27 min
## Full Body A
// Hold the bell by the horns at your chest.
Goblet Squat, Kettlebell / 3x8 / 12kg / 120s / progress: dp(4kg, 8, 12)
// Band behind your back, press forward like a push up.
Bench Press, Band / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Stand on the band, hinge and row to your hips.
Bent Over Row, Band / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~27 min
## Full Body B
// Hike the bell back, snap the hips — it's a hinge, not a squat.
Kettlebell Swing, Kettlebell / 3x8 / 12kg / 120s / progress: dp(4kg, 8, 12)
// Stand on the band, press handles overhead.
Shoulder Press, Band / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Anchor the band high, kneel and pull elbows to your sides.
Kneeling Pulldown, Band / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Step back, lightly tap the back knee down.
Reverse Lunge, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
